package com.citacloud.app.models;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.UUID;
@Entity @Table(name="productos_inventario") public class ProductoInventario { @Id @GeneratedValue private UUID id; @Column(name="empresa_id",nullable=false) private UUID empresaId; private String codigo; @Column(name="codigo_barras") private String codigoBarras; private String nombre; @ManyToOne @JoinColumn(name="categoria_id") private CategoriaInventario categoria; @ManyToOne @JoinColumn(name="unidad_id") private UnidadInventario unidad; private String descripcion; @Column(name="stock_minimo") private BigDecimal stockMinimo=BigDecimal.ZERO; @Column(name="controla_vencimiento") private boolean controlaVencimiento; @Column(name="es_facturable") private boolean esFacturable; @Column(name="precio_venta") private BigDecimal precioVenta; @Column(name="tasa_impuesto") private BigDecimal tasaImpuesto=BigDecimal.ZERO; private boolean activo=true; @Column(name="creado_por") private UUID creadoPor; @Column(name="creado_en") private LocalDateTime creadoEn; @Column(name="actualizado_en") private LocalDateTime actualizadoEn; public UUID getId(){return id;} public UUID getEmpresaId(){return empresaId;} public void setEmpresaId(UUID v){empresaId=v;} public String getCodigo(){return codigo;} public void setCodigo(String v){codigo=v;} public String getCodigoBarras(){return codigoBarras;} public void setCodigoBarras(String v){codigoBarras=v;} public String getNombre(){return nombre;} public void setNombre(String v){nombre=v;} public CategoriaInventario getCategoria(){return categoria;} public void setCategoria(CategoriaInventario v){categoria=v;} public UnidadInventario getUnidad(){return unidad;} public void setUnidad(UnidadInventario v){unidad=v;} public String getDescripcion(){return descripcion;} public void setDescripcion(String v){descripcion=v;} public BigDecimal getStockMinimo(){return stockMinimo;} public void setStockMinimo(BigDecimal v){stockMinimo=v;} public boolean isControlaVencimiento(){return controlaVencimiento;} public void setControlaVencimiento(boolean v){controlaVencimiento=v;} public boolean isEsFacturable(){return esFacturable;} public void setEsFacturable(boolean v){esFacturable=v;} public BigDecimal getPrecioVenta(){return precioVenta;} public void setPrecioVenta(BigDecimal v){precioVenta=v;} public BigDecimal getTasaImpuesto(){return tasaImpuesto;} public void setTasaImpuesto(BigDecimal v){tasaImpuesto=v;} public boolean isActivo(){return activo;} public void setActivo(boolean v){activo=v;} public void setCreadoPor(UUID v){creadoPor=v;} @PrePersist void crear(){creadoEn=actualizadoEn=LocalDateTime.now();} @PreUpdate void actualizar(){actualizadoEn=LocalDateTime.now();} }
